import argparse
import json
import re
import sys

import formats
from mutation import assign


def _tokens(q):
    # Key names, bracketed indices/quoted keys, and recursive descent.
    out=[]; i=0
    while i<len(q):
        if q.startswith('..',i): out.append(('recursive',None)); i+=2; continue
        if q[i]=='.': i+=1; continue
        if q[i]=='[':
            j=q.find(']',i+1)
            if j<0: raise ValueError('invalid selector')
            v=q[i+1:j].strip()
            if ':' in v:
                a,b=(v.split(':',1)+[''])[:2]
                out.append(('range',(int(a) if a else None,int(b) if b else None)))
            elif len(v)>1 and v[0] in "'\"": out.append(('key',v[1:-1]))
            else: out.append(('index',int(v)))
            i=j+1; continue
        m=re.match(r'[A-Za-z_$][A-Za-z0-9_$-]*|\d+',q[i:])
        if not m: raise ValueError('invalid selector')
        out.append(('key',m.group())); i+=len(m.group())
    return out


def _get(data, key):
    if isinstance(data,dict): return data[key]
    if isinstance(data,list) and isinstance(key,str) and key.isdigit(): return int(key)
    raise TypeError('expected map')


def select(data, query):
    q=query.strip()
    if not q: return data
    if q.startswith('search(') and q.endswith(')'):
        cond=q[7:-1].strip()
        m=re.fullmatch(r'([\w.-]+)\s*(==|!=)\s*(.+)',cond)
        if not m:return []
        key,op,rhs=m.groups()
        try: target=json.loads(rhs)
        except Exception: target=rhs.strip('"\'')
        matches=[]
        def walk(v):
            if isinstance(v,dict):
                if key in v and ((v[key]==target) == (op=='==')): matches.append(v)
                for x in v.values(): walk(x)
            elif isinstance(v,list):
                for x in v: walk(x)
        walk(data);return matches
    ts=_tokens(q)
    cur=[data]
    for typ,val in ts:
        nxt=[]
        if typ=='recursive':
            following=ts[ts.index((typ,val))+1][1] if ts.index((typ,val))+1<len(ts) else None
            def walk(v):
                if isinstance(v,dict):
                    if following in v:nxt.append(v[following])
                    for x in v.values():walk(x)
                elif isinstance(v,list):
                    for x in v:walk(x)
            for v in cur:walk(v)
            if following is not None:
                ts=ts[ts.index((typ,val))+1:]
                # process remaining selectors on each found value below
                cur=nxt; nxt=[]
                continue
            cur=[];continue
        for v in cur:
            if typ=='key':
                if val=='*':
                    if isinstance(v,list):nxt.extend(v)
                    elif isinstance(v,dict):nxt.extend(v.values())
                else:nxt.append(_get(v,val))
            elif typ=='index':
                if not isinstance(v,list):raise TypeError('expected array')
                nxt.append(v[val])
            elif typ=='range':
                if not isinstance(v,list):raise TypeError('expected array')
                a,b=val; nxt.append(v[a:b])
        cur=nxt
    return cur[0] if len(cur)==1 else cur


def main(argv=None):
    argv=list(sys.argv[1:] if argv is None else argv)
    if argv and argv[0]=='version': print('3.11.0'); return 0
    if argv and argv[0] in ('-h','--help'):
        print('Usage: dasel <command>\n\nQuery and modify data structures from the command line.\n\nCommands:\n  query          Execute a query\n  version        Print the version\n  interactive    Start an interactive session\n  completion     Generate shell completion script\n  man            Generate man page'); return 0
