    if fmt=='toml': return tomllib.loads(text) if tomllib else parse_toml(text)
    if fmt=='xml': return parse_xml(text, flags or {})
    if fmt=='kdl': return parse_kdl(text)
    if fmt=='csv':
        reader=csv.reader(io.StringIO(text), delimiter=(flags or {}).get('csv-delimiter', ','), strict=True)
        records=list(reader)
        if not records: return []
        header=records[0]; rows=[]
        for rec in records[1:]:
