"""Input and output format helpers for the Dasel-compatible CLI."""
import csv
import configparser
import io
import json
import xml.etree.ElementTree as ET
try:
    import tomllib
except ImportError:
    tomllib = None


def detect_format(name):
    n=(name or '').lstrip('.')
    return n or 'json'


def load_data(text, fmt='json', flags=None):
    fmt=detect_format(fmt)
    if fmt=='json':
        return None if not text.strip() else json.loads(text)
    if fmt=='toml': return tomllib.loads(text) if tomllib else parse_toml(text)
    if fmt=='xml': return parse_xml(text, flags or {})
    if fmt=='kdl': return parse_kdl(text)
    if fmt=='ini': return parse_ini(text)
    if fmt=='hcl': return parse_hcl(text)
    if fmt=='csv':
        reader=csv.reader(io.StringIO(text), delimiter=(flags or {}).get('csv-delimiter', ','), strict=True)
        records=list(reader)
        if not records: return []
        header=records[0]; rows=[]
        for rec in records[1:]:
            if len(rec)!=len(header): raise ValueError('record on line has wrong number of fields')
            rows.append(dict(zip(header,rec)))
        return rows
    if fmt == 'yaml':
        return parse_yaml(text)
    raise ValueError(f"unsupported input format: {fmt}")


def parse_hcl(text):
    import re
    root={}; stack=[root]
    def value(s):
        s=s.strip().rstrip(',')
        if s.startswith('"'):
            try:return json.loads(s)
            except Exception:return s.strip('"')
        if s in ('true','false'):return s=='true'
        if s.startswith('[') and s.endswith(']'):
            try:return json.loads(s)
            except Exception:return [value(x) for x in s[1:-1].split(',') if x.strip()]
        try:return int(s)
        except Exception:pass
        try:return float(s)
        except Exception:return s
    for raw in text.splitlines():
        line=re.split(r'\s+#|//',raw,1)[0].strip()
        if not line:continue
        if line=='}':
            if len(stack)>1:stack.pop()
            continue
        m=re.match(r'([\w.-]+)\s*\{\s*$',line)
        if m:
            obj={}; stack[-1][m.group(1)]=obj; stack.append(obj); continue
        m=re.match(r'([\w.-]+)\s*=\s*(.*?)\s*$',line)
        if m:stack[-1][m.group(1)]=value(m.group(2))
    return root


def dump_hcl(value):
    if not isinstance(value,dict): raise ValueError('hcl writer expects root output to be a map')
    lines=[]
    def atom(v):
        if isinstance(v,str):return json.dumps(v,ensure_ascii=False)
        if isinstance(v,bool):return str(v).lower()
        if isinstance(v,list):return '['+', '.join(atom(x) for x in v)+']'
        if v is None:return 'null'
        return str(v)
    def block(obj,level):
        pad='  '*level
        scalar_items=[(k,v) for k,v in obj.items() if not isinstance(v,dict)]
        width=max((len(str(k)) for k,v in scalar_items),default=0)
        for k,v in obj.items():
            if isinstance(v,dict):
                lines.extend([pad+str(k)+' {']);block(v,level+1);lines.append(pad+'}')
            else:lines.append(pad+str(k).ljust(width)+' = '+atom(v))
    block(value,0);return '\n'.join(lines)


def parse_ini(text):
    parser=configparser.ConfigParser(interpolation=None,strict=False,empty_lines_in_values=False)
    parser.optionxform=str
    if text.strip():
        source=text if text.lstrip().startswith('[') else '[__root__]\n'+text
        parser.read_string(source)
    result={}
    for section in parser.sections():
        values={key:val for key,val in parser._sections[section].items() if key!='__name__'}
        if section=='__root__': result.update(values)
        else: result[section]=values
    return result


def dump_ini(value):
    if not isinstance(value,dict): raise ValueError('ini can only represent map values')
    lines=[]
    for key,val in value.items():
        if isinstance(val,dict): continue
        if isinstance(val,list): raise ValueError('ini writer cannot represent slice values directly; consider using nested sections')
