def parse_xml(text, flags):
    if text == '': return None
    if not text.strip(): return ''
    root=ET.fromstring(text)
    if flags.get('xml-mode')=='structured':
        def node(elem):
            return {'name':elem.tag,'attrs':dict(elem.attrib),'content':elem.text or '', 'children':[node(c) for c in list(elem)]}
        return {'name':'root','attrs':{},'content':'','children':[node(root)]}
    def convert(elem):
