"""Basic mutation helpers for Dasel-style assignment selectors."""
import json
import re


def _path(text):
    parts = []
    for m in re.finditer(r"(?:^|\.)([A-Za-z_][A-Za-z0-9_-]*)|\[([0-9]+)\]|\[['\"]([^'\"]+)['\"]\]", text.strip()):
        key = next((x for x in m.groups() if x is not None), None)
        if key is None:
            continue
        parts.append(int(key) if m.group(2) is not None else key)
    return parts


def _literal(text, root):
    text = text.strip()
    try:
        return json.loads(text)
    except Exception:
        if text in ("true", "false", "null"):
            return {"true": True, "false": False, "null": None}[text]
        parts = _path(text)
        node = root
        for i, part in enumerate(parts):
            if isinstance(node, dict) and part not in node:
                prop=f'error executing ast.PropertyExpr: map key not found: {json.dumps(str(part))}'
                if i:
                    prop='error executing ast.ChainedExpr: error executing expression: '+prop
                raise ValueError('error executing selector: execution error when processing ast.BinaryExpr: error evaluating right expression: execution error when processing '+prop.replace('error executing ast.', 'ast.'))
            try: node = node[part]
            except (KeyError, IndexError, TypeError):
                raise ValueError('error executing selector: execution error when processing ast.BinaryExpr: error evaluating right expression: unexpected type or missing value')
        return node


def assign(data, query):
    """Apply a simple `path = literal` selector, returning (selected, root)."""
    m = re.fullmatch(r"\s*(.*?)\s*=\s*(.*?)\s*", query, re.S)
    if not m:
        raise ValueError("not a simple assignment")
    parts = _path(m.group(1))
    if not parts:
        raise ValueError("empty assignment path")
    value = _literal(m.group(2), data)
    node = data
    for i, part in enumerate(parts):
        if isinstance(node, dict) and part not in node:
            prop=f'ast.PropertyExpr: map key not found: {json.dumps(str(part))}'
            if i: prop='ast.ChainedExpr: error executing expression: execution error when processing '+prop
            raise ValueError('error executing selector: execution error when processing ast.BinaryExpr: error evaluating left expression: execution error when processing '+prop)
        if i == len(parts)-1:
            break
        try: node = node[part]
        except (KeyError, IndexError, TypeError):
            raise ValueError('error executing selector: execution error when processing ast.BinaryExpr: error evaluating left expression: unexpected type or missing value')
    if isinstance(node, dict) and parts[-1] not in node:
        # Kept as a separate check for the final assignment component.
        raise ValueError('error executing selector: execution error when processing ast.BinaryExpr: error evaluating left expression: execution error when processing ast.PropertyExpr: map key not found: '+json.dumps(str(parts[-1])))
    node[parts[-1]] = value
    return value, data

