def dump_data(value, fmt='json', compact=False, flags=None):
    fmt=detect_format(fmt)
    if fmt=='json':
        return json.dumps(value,ensure_ascii=False,separators=(',',':') if compact else None,indent=None if compact else 4)
    if fmt=='yaml': return dump_yaml_flow(value) if compact else dump_yaml(value)
    if fmt=='toml': return dump_toml(value)
    if fmt=='xml': return dump_xml(value)
    if fmt=='kdl': return dump_kdl(value,compact)
    if fmt=='ini': return dump_ini(value)
    if fmt=='hcl': return dump_hcl(value)
    if fmt=='csv':
        if not isinstance(value,list): raise ValueError(f'csv writer expects root output to be a slice/array, got {"null" if value is None else kind(value)}')
        if not value: return ''
        if not all(isinstance(row,dict) for row in value): raise ValueError('csv writer expects array of maps')
        fields=list(value[0].keys())
        for row in value:
            missing=next((k for k in fields if k not in row),None)
            if missing is not None: raise ValueError(f'error ranging slice: error getting map key "{missing}": map key not found: "{missing}"')
        s=io.StringIO(newline=''); w=csv.DictWriter(s,fieldnames=fields,delimiter=(flags or {}).get('csv-delimiter',','),lineterminator='\n',extrasaction='ignore'); w.writeheader(); w.writerows(value)
        return s.getvalue().rstrip('\n')
    raise ValueError(f'unsupported output format: {fmt}')


def kind(v):
    return {dict:'map',list:'slice',str:'string',bool:'bool',int:'int',float:'float',type(None):'null'}.get(type(v),'value')

